export class PriceService {quote(netCents,taxBasisPoints){if(!Number.isSafeInteger(netCents)||!Number.isSafeInteger(taxBasisPoints)||netCents<0||taxBasisPoints<0)throw new Error('Invalid price');return netCents+Math.round(netCents*taxBasisPoints/10000);}}
export class PriceAdapter {constructor(){this.service=new PriceService();}quote(netCents,taxBasisPoints){return this.service.quote(netCents,taxBasisPoints);}}
export class PriceFacade {constructor(){this.adapter=new PriceAdapter();}quote(netCents,taxBasisPoints){return this.adapter.quote(netCents,taxBasisPoints);}}
export const quote=(netCents,taxBasisPoints)=>new PriceFacade().quote(netCents,taxBasisPoints);
